//! Multiparameter density iteration comparisons against the exact-source library.
//! Generated by tools/rust_port/validate_meos_density.py.
//! Copyright thermotools and Contributors. Apache-2.0.

#![allow(clippy::excessive_precision)]

use thermopack_rs::{LennardJonesKind, Multiparameter};

/// The residual kernel agrees with the source to about 1e-14 relative, and a
/// Newton step divides the pressure error by dP/drho. The density tolerance
/// therefore adds the conditioning term of the state.
const EPS_P: f64 = 1e-14;
const ATOL: [f64; 5] = [1e-8, 0., 0., 1e-4, 1e-5];
const RTOL: f64 = 2e-8;

fn model(eos: &str, component: &str) -> Multiparameter {
    match eos {
        "LJ_MEOS" => {
            Multiparameter::lennard_jones(component, LennardJonesKind::Full).expect("model")
        }
        "LJTS_MEOS" => Multiparameter::lennard_jones(component, LennardJonesKind::TruncatedShifted)
            .expect("model"),
        "LJTS_REDUCED" => Multiparameter::reduced_lennard_jones_truncated_shifted(),
        _ => Multiparameter::new(component).expect("model"),
    }
}

/// Split a case key into the model, the state and the phase flag.
fn parse(case: &str) -> (&str, &str, f64, f64, i32) {
    let parts: Vec<_> = case.split('|').collect();
    let (eos, component) = parts[1].split_once(':').expect("model key");
    (
        eos,
        component,
        parts[2].parse().expect("temperature"),
        parts[3].parse().expect("pressure"),
        parts[4].parse().expect("phase"),
    )
}

#[test]
fn multiparameter_density_matches_the_source() {
    let mut checked = 0;
    let mut relaxed = 0;
    for row in include_str!("fixtures/meos_density.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let (eos, component, temperature, pressure, phase) = parse(case);
        let model = model(eos, component);
        let prepared = model.prepare(temperature).expect("prepare");
        let result = prepared
            .baseline_density_with_phase_code(pressure, phase)
            .unwrap_or_else(|error| panic!("{case}: {error}"));
        let expected: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        let actual = [
            result.density,
            result.phase as f64,
            result.source_error_code as f64,
            result.pressure,
            result.pressure_density_derivative,
        ];
        if result.relaxed_convergence {
            relaxed += 1;
        }
        for (position, (source, native)) in expected.iter().zip(actual.iter()).enumerate() {
            let mut tolerance = ATOL[position] + RTOL * source.abs().max(native.abs());
            if position == 0 {
                tolerance += EPS_P * expected[3].abs() / expected[4].abs().max(f64::MIN_POSITIVE);
            }
            assert!(
                (source - native).abs() <= tolerance,
                "{case} quantity {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 1669);
    // The relaxed criterion is a last resort for a stalled iteration and
    // stays rare.
    assert!(relaxed < 32, "relaxed convergence in {relaxed} cases");
}

#[test]
fn multiparameter_density_reports_the_source_failures() {
    // The recorded source terminations are the phase flags that the original
    // ancillary rejects, which the native model must also refuse.
    let metadata = include_str!("fixtures/meos_density.metadata.json");
    let section = metadata
        .split("\"reference_errors\"")
        .nth(1)
        .expect("reference errors")
        .split("\"censored_reference_calls\"")
        .next()
        .expect("reference errors section");
    let mut failures = 0;
    for chunk in section.split("\"case\": \"").skip(1) {
        let case = chunk.split('"').next().expect("case key");
        let (eos, component, temperature, pressure, phase) = parse(case);
        let model = model(eos, component);
        let prepared = model.prepare(temperature).expect("prepare");
        assert!(
            prepared
                .baseline_density_with_phase_code(pressure, phase)
                .is_err(),
            "{case} should fail like the source"
        );
        failures += 1;
    }
    assert_eq!(failures, 25);
}

#[test]
fn multiparameter_density_rejects_unusable_states() {
    let model = Multiparameter::new("C3").expect("model");
    let prepared = model.prepare(300.0).expect("prepare");
    // A nonpositive pressure is invalid.
    assert!(prepared.baseline_density_with_phase_code(0.0, 1).is_err());
    // The minimum Gibbs phase flag has no density branch.
    assert!(prepared.baseline_density_with_phase_code(1e5, 3).is_err());
    // A valid state reports a positive density with a closed pressure.
    let result = prepared
        .baseline_density_with_phase_code(1e5, 2)
        .expect("density");
    assert!(result.density > 0.0);
    assert!(result.pressure_converged);
}
